"""Whole checked numeric conversion implementation and private parser interface."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='파서 · 진법·범위 검사·실패 원자성·사용자 메모리',
                     sections=sections, questions=questions))


add('include/linux/kstrtox.h', '문자열 변환 공개 계약: 타입 폭과 반환값 검사',
    '정수와 불리언 변환의 선언, 타입별 inline 연결, 사용자 메모리용 변환 인터페이스를 모은 헤더입니다.',
    'long과 long long의 크기·정렬을 비교해 호출 경로를 고르고, 고정 폭 이름은 대응하는 기본 정수 함수로 연결합니다. 반환 상태를 확인해야 출력값의 유효성을 알 수 있습니다.',
    '문자열이 NUL로 종료되는지, 원하는 진법과 결과 타입이 무엇인지 먼저 결정합니다. 사용자 포인터에는 count를 받는 from_user 인터페이스를 사용합니다.',
    [('전체 선언 구조', 'SPDX와 include guard, compiler/types 포함으로 시작합니다. 내부 long 함수와 long long 함수, 문서가 붙은 long inline 두 개, int와 고정 폭 함수, bool, from_user 선언과 inline, 마지막으로 simple_strto 계열의 주의사항과 선언 네 개를 제공합니다.'),
     ('크기와 정렬에 따른 long 경로', 'kstrtoul은 unsigned long과 unsigned long long의 sizeof와 __alignof__가 모두 같으면 결과 포인터를 변환해 kstrtoull로 전달합니다. 다르면 _kstrtoul이 범위를 검사합니다. kstrtol도 signed 타입으로 같은 선택을 합니다. 서로 다른 C 타입이라 __builtin_types_compatible_p가 0이라는 주석은 왜 타입 동일성 대신 레이아웃 조건을 쓰는지 설명합니다.'),
     ('최적화와 언어 규칙', 'sizeof와 정렬은 컴파일 시 결정되므로 inline 내부의 조건은 대상 아키텍처에 맞게 제거될 수 있습니다. 이 커널 코드의 포인터 변환을 크기만 같은 모든 사용자 공간 타입에 일반화하면 안 됩니다. 별칭 접근 규칙과 커널 빌드 조건도 함께 고려해야 합니다.'),
     ('고정 폭 이름의 연결', 'kstrtou64/kstrtos64는 ull/ll로, kstrtou32/kstrtos32는 uint/int로 전달합니다. 16비트와 8비트 함수는 외부 선언이며 실제 범위 검사는 lib/kstrtox.c에 있습니다. inline은 별도의 문자열 문법을 추가하지 않습니다.'),
     ('반환 상태와 문법', '__must_check는 결과 확인을 요구하는 컴파일러 주석입니다. 런타임에 오류를 자동 처리하는 기능은 아닙니다. 문서는 0 성공, -ERANGE 범위 초과, -EINVAL 문법 오류와 선택적 개행 하나를 설명합니다. unsigned는 +를 허용하지만 -는 허용하지 않습니다. base0은 0x/0 접두사로 진법을 결정하며 최대 지원 진법은 16입니다.'),
     ('사용자 포인터 인터페이스', 'from_user 선언은 __user 포인터와 size_t count를 받습니다. bool만 진법 인자가 없고 정수에는 진법이 있습니다. 고정 폭 64/32비트 inline 네 개는 대응 from_user 함수로 모든 인자를 전달합니다. __user 표시는 주소 공간 검사를 돕지만 실제 안전한 복사는 구현이 담당합니다.'),
     ('simple_strto를 예외적으로 쓰는 이유', '마지막 주석은 기본적으로 kstrto 계열을 사용하라고 안내합니다. simple_strto는 범위 오버플로를 검사하지 않고 첫 비숫자에서 멈추며 끝 위치를 char **로 전달할 수 있습니다. 10x50 또는 12:21처럼 구분자로 이어진 입력을 처리하는 용도가 있지만, 부분 소비가 필요하다는 이유로 범위 검사를 생략해도 된다는 뜻은 아닙니다.'),
     ('CS 연결과 실행 검증 범위', '표현 폭과 타입 동일성의 차이, 컴파일 시 분기, 오류 채널과 출력 채널의 분리, 전체 파싱과 부분 파싱을 학습합니다. 별도 kstrtox 실행 검사는 구현의 문법·범위 경계를 확인하며 이 헤더의 모든 아키텍처별 inline 경로나 실제 사용자 주소 공간을 검증한 것은 아닙니다.')],
    [('long과 long long의 크기만 같으면 빠른 경로를 선택하는가?', '아니다. 정렬도 같아야 한다', '그렇다. sizeof만 비교한다', '조건에는 sizeof 비교와 __alignof__ 비교가 &&로 연결됩니다. 둘 중 하나라도 다르면 내부 long 변환 함수로 갑니다.'),
     ('__must_check가 오류를 자동으로 복구하는가?', '아니다. 호출자가 반환값을 확인하고 처리해야 한다', '그렇다. 실패하면 자동으로 기본값을 쓴다', '이 표시는 반환값 무시를 진단하도록 돕습니다. 성공 여부에 따른 제어 흐름과 출력 사용은 호출자가 작성해야 합니다.'),
     ('12:21의 앞부분을 읽는 simple_strtol을 선택했다면 무엇을 추가로 고려해야 하는가?', '끝 위치와 수치 범위를 별도로 검증해야 한다', '오버플로 검사가 내장되어 있으므로 값만 사용한다', '헤더는 simple_strto가 범위 오버플로를 검사하지 않는다고 명시합니다. 부분 파싱과 안전한 범위 검증은 서로 다른 요구입니다.')])


add('lib/kstrtox.c', '문자열 변환 전체: 정수 범위 검사와 불리언 접두사',
    '정수 문법·출력 타입·사용자 메모리 접근을 단계별로 분리한 변환 구현입니다.',
    '진법 보정과 숫자 누적을 내부 helper로 수행한 뒤 오류·종료 문자를 검사합니다. 각 공개 정수 함수는 범위 검사를 통과한 후에만 출력값을 씁니다. 불리언은 별도의 접두사 규칙을 사용합니다.',
    '정수 입력은 유효한 NUL 종료 문자열과 지원 진법을 제공해야 합니다. 모든 함수가 NULL 문자열을 검사하는 것은 아니며 불리언의 느슨한 문법을 숫자 변환에 적용하면 안 됩니다.',
    [('파일 전체 구성', 'SPDX·문법 설명,ctype/errno/export/kstrtox/math64/types/uaccess와 내부 헤더 포함,진법 보정·누적 helper,64비트 signed/unsigned 파서,좁은 타입 wrapper,불리언과 from_user 구현,10개 from_user 함수 생성으로 끝납니다. 주요 함수는 noinline과 export로 연결됩니다.'),
     ('진법 보정', '_parse_integer_fixup_radix는 base0에서 선행0x와 뒤의 유효16진 숫자를 확인하면16,그 외 선행0은8,나머지는10을 선택합니다. base16이면0x/0X 접두사를 건너뜁니다. 따라서 자동진법 "010"은8이며 "09"는뒤의9가8진숫자가아니어서공개파서에서실패합니다. 선택한진법의지원범위는호출계약을지켜야합니다.'),
     ('숫자 누적과 내부 오류 표현', '_parse_integer_limit는 최대 max_chars까지0..9,a..f를 해석하고 res=res*base+val로 누적합니다. 현재 결과의 상위4비트가 켜지면 (ULLONG_MAX-val)/base와 비교하여 overflow 비트를 켭니다. 오버플로가 있어도 내부 출력값을 쓰고 소비 문자 수와 bit31 오류 플래그를 함께 반환합니다. 내부 helper의 출력 규칙과 공개 API의 실패 시 출력 보존을 혼동하지 않습니다.'),
     ('엄격한 unsigned 종료 검사', '_parse_integer는 제한을 INT_MAX로 둡니다. _kstrtoull은 overflow면-ERANGE,숫자를하나도읽지못하면-EINVAL,숫자뒤에는선택적개행하나와NUL만허용합니다. 중간공백·뒤쪽문자·개행두개는통과하지않습니다. 성공시에만외부res를갱신합니다. kstrtoull은앞의+하나를허용하지만-는허용하지않습니다.'),
     ('signed64와 최소값', 'kstrtoll은-접두사를 별도로 처리하고 크기를 unsigned로 읽습니다. 음수 경로는 unsigned 부호 반전과 signed 변환 결과의 부호를 확인하고,양수 경로도 signed 최대 범위를 넘는지 검사합니다. 해당 커널 정수 표현에서 LLONG_MIN까지 다루도록 구성되며 임의의 사용자 공간 C 구현의 변환 규칙까지 동일하다고 주장하지 않습니다.'),
     ('좁은 타입 wrapper 전체', '_kstrtoul/_kstrtol,kstrtouint/kstrtoint,kstrtou16/kstrtos16,kstrtou8/kstrtos8은 넓은 임시값으로 파싱한 뒤 대상 타입으로 변환한 값과 원래값을 비교합니다. 다르면-ERANGE이고 출력은 쓰지 않습니다. 파싱 오류도 그대로 전파합니다. 타입 폭 검사와 문자열 문법 검사를 단계적으로 결합합니다.'),
     ('불리언의 다른 문법', 'kstrtobool은 NULL이면-EINVAL입니다. 첫문자Y/y/T/t/1은참,N/n/F/f/0은거짓이며,o/O로시작하면둘째문자N/n또는F/f를검사합니다. 따라서 "yes-extra"와 "truejunk"도참,"of-anything"은거짓이될수있습니다. "off"전체철자를검사하지않습니다. 일치한경로에서만res를씁니다.'),
     ('불리언 사용자 복사', 'kstrtobool_from_user는4바이트지역버퍼를쓰고최대3바이트만복사한뒤NUL을붙입니다. copy_from_user의비영반환은-EFAULT입니다. 긴입력을전부검사하지않고필요한접두사만전달합니다. count0이면빈문자열파싱으로-EINVAL이됩니다.'),
     ('숫자 사용자 복사10종', 'kstrto_from_user 매크로는 부호+타입비트수의2진표현+개행+NUL 크기의 지역버퍼를 만듭니다. count를 버퍼크기-1로 제한하고 복사·NUL종료 후 대응 파서를 호출합니다. unsigned/signed long long,long,int,16비트,8비트의10종을 생성합니다. 입력 전체가 너무 길다고 별도 거부하는 것이 아니라 잘린 접두사를 파싱하므로 원래 count 전체를 검증했다고 표현하면 안 됩니다.'),
     ('CS와 검증 경계', '접두사 기반 문법과 전체 문자열 문법,오버플로 전 검사,오류 플래그와 길이의 공동 인코딩,성공 후 출력 대입,사용자 메모리 복사 실패를 연결합니다. copy_from_user 이후 파싱은 커널 버퍼에서 이루어지지만 원본 문자열 전체의 원자적 스냅샷이나 실제 페이지 폴트 동작을 보장하는 검증은 별도입니다.')],
    [('자동진법에서 "010"과 "09"는?', '각각8과파싱오류다', '둘다10진수로10과9다', '선행0은8진수 선택입니다.9를소비하지못하면뒤쪽문자검사에서-EINVAL이됩니다.'),
     ('숫자 문자열 뒤 개행은 몇 개까지 허용하는가?', '최대하나이며그뒤NUL이어야한다', '개수와상관없이모두건너뛴다', '_kstrtoull은개행이면포인터를한번만증가시키고다음문자가있으면거부합니다.'),
     ('내부 누적 helper도 overflow 시 출력값을 보존하는가?', '아니다. 내부 helper는값을쓰고플래그를돌려준다', '그렇다.공개함수와완전히같다', '공개함수는지역임시값을사용해성공시에만호출자출력을갱신합니다. 계층별계약을구분해야합니다.'),
     ('kstrtobool("of-anything")은?', '성공하며거짓으로판정한다', 'off와정확히같지않아실패한다', '첫문자o와둘째문자f만검사합니다. 뒤쪽문자전체의동등성을검사하지않습니다.'),
     ('kstrtou8의입력256은?', '-ERANGE이며출력은갱신하지않는다', '성공하며0으로조용히잘린다', '넓은값256과u8변환값0을비교해범위오류로판정합니다.'),
     ('from_user가항상원래count전체를검증하는가?', '아니다. 지역버퍼한도만큼복사한접두사를파싱한다', '그렇다. 긴입력을여러번나누어끝까지검사한다', 'count=min(count,sizeof(buf)-1)이며추가반복복사가없습니다. 문자열전체검증과구분해야합니다.')])

add('lib/kstrtox.h', '내부 정수 파서 헤더 전체: 길이와 overflow 비트',
    '공개 변환 API 안쪽에서 사용하는 숫자 누적 helper의 선언입니다.',
    'KSTRTOX_OVERFLOW는1U<<31이고 진법 보정,최대문자수 제한 파서,기본 제한 파서의3개 함수를 선언합니다.',
    '내부 반환값은 단순 오류 코드가 아니라 소비 길이와 overflow 표시를 합친 unsigned 값입니다. 공개 API의0/-errno와 혼동하지 않습니다.',
    [('전체 파일', 'SPDX,_LIB_KSTRTOX_H guard,상수하나,함수선언3개,#endif로끝납니다. size_t를사용하지만별도타입헤더include는없어포함문맥에의존합니다.'),
     ('함수별 역할', '_parse_integer_fixup_radix는base 포인터를갱신하고숫자시작포인터를반환합니다. _parse_integer_limit는명시적진법·출력저장소·최대문자수를받습니다. _parse_integer는최대문자수인자가없는wrapper입니다. 실제알고리즘은같은디렉터리의C파일에있습니다.'),
     ('플래그 해석', '소비문자수에최상위비트를OR하여overflow를알립니다. 호출자가이를그대로문자열포인터에더하면잘못된길이가됩니다. 공개파서는플래그를먼저확인해오류로반환하고정상길이일때만입력위치를이동합니다.'),
     ('CS 연결', '하나의정수반환값에상태와길이를함께담는표현,private/public API분리,출력포인터의계약을학습합니다. 내부선언이보인다는이유만으로일반문자열변환사용처에서직접호출할안전한인터페이스라고가정하지않습니다.')],
    [('KSTRTOX_OVERFLOW는어떤값인가?', 'unsigned의31번비트표시인1U<<31', '소비문자수의최대값31', '비트위치와숫자값을구분합니다.반환길이와함께OR되는상태플래그입니다.'),
     ('내부 반환값을곧바로입력포인터에더해도되는가?', '안 된다. overflow플래그를먼저확인해야한다', '된다. 항상순수한문자수다', '오류플래그가포함된값은실제소비길이가아닙니다.공개파서의검사순서를따라읽어야합니다.')])
